#!/usr/bin/env bash
# projects/{{JOB}}/prune.sh — reclaim regenerable cache ONLY.
#
# LOCK: never touch raw/ or outputs/. Everything this script deletes
# must be rebuildable from raw/ + transcript/words.json + cutlist.json.
#
# Generated by scripts/new-project.sh from lib/templates/prune.sh.
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "$here/../.." && pwd)"
. "$repo/lib/common.sh"

job="{{JOB}}"

reclaim() {
  path="$1"
  if [ -e "$path" ]; then
    size="$(du -sh "$path" 2>/dev/null | awk '{print $1}')"
    rm -rf "$path"
    hf_log "removed $path ($size)"
  fi
}

hf_log "pruning regenerable cache for $job (raw/ and outputs/ are never touched)"

# whole-file caches, safe to regenerate from raw/
reclaim "$here/.cache/raw-audio.wav"
reclaim "$here/.cache/assembled.mov"

# HyperFrames graphics build cache — parts are re-rendered from the
# shared timeline in hf-graphics/, not deleted; only its OWN build/tmp
# output goes here, never the timeline source itself.
reclaim "$here/hf-graphics/.hf-cache"
reclaim "$here/hf-graphics/dist"

hf_log "done. raw/ and outputs/ untouched."
